// @pit: {"label": "Move sub inside summary, update tests, rerender and rerun check"}
async ({ workspace: { read, edit }, shell: { exec } }) => {
  const oldS = "`<sub><details><summary>🧵 This conversation is stored in git on <code>${ref}</code></summary>`,";
  const newS = "`<details><summary><sub>🧵 This conversation is stored in git on <code>${ref}</code></sub></summary>`,";
  for (const file of ["src/formatting.ts", "src/formatting.test.ts"]) {
    const r = await read(file, { format: "raw" });
    if (!r.content.includes(oldS)) return "missing in " + file;
    await edit(file, { revision: r.revision, changes: [{ kind: "replaceFile", content: r.content.replace(oldS, newS).replace('"</details></sub>",', '"</details>",') }] });
  }
  const t = await read("src/run.test.ts", { format: "raw" });
  await edit("src/run.test.ts", { revision: t.revision, changes: [{ kind: "replaceFile", content: t.content.replace("`<summary>🧵 This conversation is stored in git on <code>${REF}</code></summary>`", "`<summary><sub>🧵 This conversation is stored in git on <code>${REF}</code></sub></summary>`") }] });
  await exec("node /tmp/render.mjs > /tmp/body.json");
  const html = (await exec("gh api markdown --input /tmp/body.json")).stdout;
  await exec("npx oxfmt src/formatting.ts src/formatting.test.ts src/run.test.ts");
  const c = (await exec("npm run check 2>&1 | grep -vE '✓|^\\s+\\S+\\.ts\\s+\\|' | grep -E 'error|FAIL|×|Found|Unused|Tests |clones' | head -20", { timeoutMs: 280000 })).stdout;
  return { html: html.slice(0, 400), c };
}
